css='''body{margin:0;background:#09111c;color:#eef4fc;font:16px/1.55 -apple-system,BlinkMacSystemFont,sans-serif}main{max-width:1120px;margin:auto;padding:32px 22px}h1{font-size:35px;line-height:1.15}h2{margin-top:36px}p{max-width:920px}.muted{color:#adbed2}section,.card{background:#111f30;border:1px solid #293f55;border-radius:14px;padding:20px;margin:18px 0}.grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(250px,1fr));gap:16px}.grid .card{margin:0}.grid img{width:100%;height:440px;object-fit:contain;background:#07101c}img.wide{width:100%}button,select,textarea{font:inherit;border:1px solid #46637e;background:#182f46;color:#fff;padding:10px;border-radius:8px}button{cursor:pointer;margin:5px}button:hover{background:#2d506f}a{color:#91d4ff}video{width:100%;max-height:650px;background:#02070e}textarea{display:block;width:95%;margin-top:10px}.tag{display:inline-block;border:1px solid #68829c;padding:4px 10px;border-radius:30px}.decision{margin-top:12px}summary{cursor:pointer}table{width:100%;border-collapse:collapse}td,th{text-align:left;padding:8px;border-bottom:1px solid #385069}'''
def image(name):
 p=O/f'stills/{name}.jpg'
 return f'<a href="stills/{name}.jpg"><img loading="lazy" src="stills/{name}.jpg" alt="{name}"></a>' if p.exists() else '<p class="muted">Moving-source inspection pending. No finished asset claimed.</p>'
def control(id):return f'<div class="decision"><label>{id}: <select data-id="{id}"><option value="pending">Pending</option><option>Approve</option><option>Changes requested</option><option>Remove</option></select></label><textarea data-note="{id}" rows="2" placeholder="Notes"></textarea></div>'
def play(name,label):return f'<button onclick="play(\'{name}\')">{label}</button>'
s=f'<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Most Guys Abs AD R1</title><style>{css}</style></head><body><main><span class="tag">AD / RA-13 / Round 1</span><h1>Why Do Most Guys Never Get Abs?</h1><p>Look and asset review. The selected narration is approximately <b>54.5 seconds</b>. This is the first approval round, not the finished ad.</p><p class="muted">Locked from previous work: Soft Blue Light graphics; same-person Dan demonstration source. Still pending: this footage\'s color, crops, audio, exact asset timing, opening, both full masters and independent final audit.</p><h2>Your decisions (3)</h2><p>Choose a color, approve or adjust the wide/close framing pair, and choose a voice treatment. Recommendations: B, the wider pair shown here, and lighter bass.</p><section><h2>One player for all previews</h2><video id="player" src="audio/lighter-bass.wav" controls preload="none" playsinline poster="stills/B-256.jpg"></video><p id="now" class="muted">Select a sample below.</p>'
